<script setup lang="ts">
import type { BsFxChoices, BsFxCopy, BsFxForm, BsFxItemForm, BsFxSettlementForm, BsFxRevaluationForm, BsFxMappingForm, BsFxReversalForm, BsFxView } from '../types/foreignExchangePresentation'
defineProps<{ copy: BsFxCopy; view: BsFxView; choices: BsFxChoices }>()
const form = defineModel<BsFxForm>('form', { required: true })
const emit = defineEmits<{ retry: []; mapping: []; item: []; settlement: []; preview: []; confirm: []; reversal: [] }>()
function item<K extends keyof BsFxItemForm>(key: K, value: BsFxItemForm[K]) { form.value = { ...form.value, item: { ...form.value.item, [key]: value } } }
function settlement<K extends keyof BsFxSettlementForm>(key: K, value: BsFxSettlementForm[K]) { form.value = { ...form.value, settlement: { ...form.value.settlement, [key]: value } } }
function revaluation<K extends keyof BsFxRevaluationForm>(key: K, value: BsFxRevaluationForm[K]) { form.value = { ...form.value, revaluation: { ...form.value.revaluation, [key]: value } } }
function mapping<K extends keyof BsFxMappingForm>(key: K, value: BsFxMappingForm[K]) { form.value = { ...form.value, mapping: { ...form.value.mapping, [key]: value } } }
function reversal<K extends keyof BsFxReversalForm>(key: K, value: BsFxReversalForm[K]) { form.value = { ...form.value, reversal: { ...form.value.reversal, [key]: value } } }
function allocation(id: string, key: 'document' | 'settlement' | 'rate' | 'evidence', value: string) { settlement('rows', { ...form.value.settlement.rows, [id]: { document: '', settlement: '', rate: '', evidence: '', ...form.value.settlement.rows[id], [key]: value } }) }
function closingRate(currency: string, key: 'rate' | 'reference', value: string) { revaluation('rates', { ...form.value.revaluation.rates, [currency]: { rate: '', reference: '', ...form.value.revaluation.rates[currency], [key]: value } }) }
</script>
<template>
  <BsCard v-if="view.visible" data-testid="fx-panel" as="section" padding="lg">
    <BsHeading :level="2">{{ copy.title }}</BsHeading><BsText size="sm" tone="muted">{{ copy.policy }}</BsText>
    <BsTabs :model-value="form.tab" :tabs="choices.tabs" :label="copy.title" @update:model-value="form = { ...form, tab: $event }"/>
    <BsText v-if="view.error" role="alert" tone="danger">{{ copy.loadError }}<BsButton @click="emit('retry')">{{ copy.retry }}</BsButton></BsText>
    <BsSectionSkeleton v-else-if="view.loading" variant="table" :rows="3"/>
    <BsStack v-else gap="md">
      <BsText v-if="view.failure" role="alert" tone="danger">{{ copy.saveError }} · {{ view.failure }}</BsText><BsText v-if="view.message" role="status">{{ view.message }}</BsText>
      <BsText v-if="!view.mapped && form.tab !== 'mapping'" tone="warning">{{ copy.mappingRequired }}</BsText><BsText v-if="view.mapped && form.tab === 'mapping'" role="status">{{ copy.mappingConfigured }}</BsText>
      <BsForm v-if="form.tab === 'mapping' && !view.mapped" layout="grid" :columns="2" @submit.prevent="emit('mapping')">
        <BsFloatingField v-for="key in (['realizedGain', 'realizedLoss', 'unrealizedGain', 'unrealizedLoss'] as const)" :key="key" :label="copy[key]"><BsSelect :model-value="form.mapping[key]" :label="copy[key]" :options="key === 'realizedGain' || key === 'unrealizedGain' ? choices.gains : choices.losses" option-label="label" option-value="value" native required @update:model-value="mapping(key, String($event))"/></BsFloatingField><BsButton type="submit" :disabled="view.mappingDisabled" variant="primary">{{ copy.save }}</BsButton>
      </BsForm>
      <BsForm v-if="form.tab === 'item'" layout="grid" :columns="2" @submit.prevent="emit('item')">
        <BsFloatingField :label="copy.counterparty"><BsSelect :model-value="form.item.counterparty" :label="copy.counterparty" :options="choices.counterparties" option-label="label" option-value="value" required native @update:model-value="item('counterparty', String($event))"/></BsFloatingField>
        <BsFloatingField :label="copy.control"><BsSelect :model-value="form.item.control" :label="copy.control" :options="choices.controls" option-label="label" option-value="value" required native @update:model-value="item('control', String($event))"/></BsFloatingField>
        <BsFloatingField :label="copy.offset"><BsSelect :model-value="form.item.offset" :label="copy.offset" :options="choices.offsets" option-label="label" option-value="value" required native @update:model-value="item('offset', String($event))"/></BsFloatingField>
        <BsFloatingField :label="copy.currency"><BsSelect :model-value="form.item.currency" :label="copy.currency" :options="choices.currencies" option-label="label" option-value="value" native @update:model-value="item('currency', String($event))"/></BsFloatingField>
        <BsFloatingField :label="copy.documentDate"><BsInput :model-value="form.item.date" type="date" required @update:model-value="item('date', String($event ?? ''))"/></BsFloatingField><BsFloatingField :label="copy.dueDate"><BsInput :model-value="form.item.due" type="date" :min="form.item.date" required @update:model-value="item('due', String($event ?? ''))"/></BsFloatingField>
        <BsFloatingField v-for="field in ([['reference', copy.reference], ['amount', copy.amount], ['rate', copy.baseRate], ['source', copy.rateSource], ['evidence', copy.rateEvidence]] as const)" :key="field[0]" :label="field[1]"><BsInput :model-value="form.item[field[0]]" :inputmode="field[0] === 'amount' || field[0] === 'rate' ? 'decimal' : undefined" required @update:model-value="item(field[0], String($event ?? ''))"/></BsFloatingField>
        <BsButton type="submit" :disabled="view.itemDisabled" variant="primary">{{ copy.postItem }}</BsButton>
      </BsForm>
      <BsForm v-if="form.tab === 'settlement'" @submit.prevent="emit('settlement')">
        <BsGrid :columns="2">
          <BsFloatingField :label="copy.counterparty"><BsSelect :model-value="form.settlement.counterparty" :label="copy.counterparty" :options="choices.counterparties" option-label="label" option-value="value" required native @update:model-value="settlement('counterparty', String($event))"/></BsFloatingField>
          <BsFloatingField :label="copy.control"><BsSelect :model-value="form.settlement.control" :label="copy.control" :options="choices.controls" option-label="label" option-value="value" required native @update:model-value="settlement('control', String($event))"/></BsFloatingField>
          <BsFloatingField :label="copy.cash"><BsSelect :model-value="form.settlement.cash" :label="copy.cash" :options="choices.cash" option-label="label" option-value="value" required native @update:model-value="settlement('cash', String($event))"/></BsFloatingField>
          <BsFloatingField :label="copy.currency"><BsSelect :model-value="form.settlement.currency" :label="copy.currency" :options="choices.currencies" option-label="label" option-value="value" native @update:model-value="settlement('currency', String($event))"/></BsFloatingField>
          <BsFloatingField :label="copy.settlementDate"><BsInput :model-value="form.settlement.date" type="date" required @update:model-value="settlement('date', String($event ?? ''))"/></BsFloatingField>
          <BsFloatingField v-for="field in ([['reference', copy.reference], ['gross', copy.gross], ['rate', copy.baseRate], ['source', copy.rateSource], ['evidence', copy.rateEvidence]] as const)" :key="field[0]" :label="field[1]"><BsInput :model-value="form.settlement[field[0]]" required @update:model-value="settlement(field[0], String($event ?? ''))"/></BsFloatingField>
        </BsGrid>
        <BsBox v-for="row in view.eligible" :key="row.id" padding="md" border><BsText emphasis="bold">{{ row.reference }} · {{ row.currency }} {{ row.outstanding }}</BsText><BsGrid :columns="4">
          <BsFloatingField v-for="field in ([['document', copy.documentAmount], ['settlement', copy.settlementAmount], ['rate', copy.crossRate], ['evidence', copy.conversionEvidence]] as const)" :key="field[0]" :label="field[1]"><BsInput :model-value="form.settlement.rows[row.id]?.[field[0]]" @update:model-value="allocation(row.id, field[0], String($event ?? ''))"/></BsFloatingField>
        </BsGrid><BsText size="xs" tone="muted">{{ copy.expected }}: {{ row.expected }} {{ form.settlement.currency }} {{ copy.minorUnits }}</BsText></BsBox>
        <BsButton type="submit" :disabled="view.settlementDisabled" variant="primary">{{ copy.postSettlement }}</BsButton>
      </BsForm>
      <BsForm v-if="form.tab === 'revaluation'" @submit.prevent="emit('preview')"><BsGrid :columns="2">
        <BsFloatingField :label="copy.control"><BsSelect :model-value="form.revaluation.control" :label="copy.control" :options="choices.controls" option-label="label" option-value="value" required native @update:model-value="revaluation('control', String($event))"/></BsFloatingField>
        <BsFloatingField :label="copy.reference"><BsInput :model-value="form.revaluation.reference" required @update:model-value="revaluation('reference', String($event ?? ''))"/></BsFloatingField><BsFloatingField :label="copy.rateSource"><BsInput :model-value="form.revaluation.source" required @update:model-value="revaluation('source', String($event ?? ''))"/></BsFloatingField>
      </BsGrid><BsGrid v-for="currency in view.rateCurrencies" :key="currency" :columns="2"><BsFloatingField :label="`${currency} · ${copy.closingRate}`"><BsInput :model-value="form.revaluation.rates[currency]?.rate" required @update:model-value="closingRate(currency, 'rate', String($event ?? ''))"/></BsFloatingField><BsFloatingField :label="copy.rateEvidence"><BsInput :model-value="form.revaluation.rates[currency]?.reference" required @update:model-value="closingRate(currency, 'reference', String($event ?? ''))"/></BsFloatingField></BsGrid><BsButton type="submit" :disabled="view.previewDisabled">{{ copy.preview }}</BsButton></BsForm>
      <BsStack v-if="view.preview.length"><BsDataTable :value="view.preview" data-key="id" :label="copy.preview" :columns="[{ key: 'reference', field: 'reference', header: copy.reference }, { key: 'currency', field: 'currency', header: copy.currency }, { key: 'outstanding', field: 'outstanding', header: copy.outstanding }, { key: 'carrying', field: 'carrying', header: copy.currentCarrying }, { key: 'closing', field: 'closing', header: copy.closingBase }, { key: 'delta', field: 'delta', header: copy.delta }]"/><BsButton :disabled="view.confirmDisabled" variant="primary" @click="emit('confirm')">{{ copy.confirm }}</BsButton></BsStack>
      <BsForm v-if="form.tab === 'reversal'" layout="grid" :columns="2" @submit.prevent="emit('reversal')"><BsFloatingField :label="copy.reversalKind"><BsSelect :model-value="form.reversal.kind" :label="copy.reversalKind" :options="choices.reversalKinds" option-label="label" option-value="value" native @update:model-value="reversal('kind', String($event))"/></BsFloatingField><BsFloatingField :label="copy.reversalTarget"><BsSelect :model-value="form.reversal.id" :label="copy.reversalTarget" :options="choices.reversalTargets" option-label="label" option-value="value" native required @update:model-value="reversal('id', String($event))"/></BsFloatingField><BsFloatingField :label="copy.reversalDate"><BsInput :model-value="form.reversal.date" type="date" required @update:model-value="reversal('date', String($event ?? ''))"/></BsFloatingField><BsFloatingField :label="copy.reversalReason"><BsInput :model-value="form.reversal.reason" required @update:model-value="reversal('reason', String($event ?? ''))"/></BsFloatingField><BsText size="sm" tone="muted">{{ copy.reversalPolicy }}</BsText><BsButton type="submit" :disabled="view.reversalDisabled" variant="primary">{{ copy.postReversal }}</BsButton></BsForm>
      <BsDataTable :value="view.items" data-key="id" :label="copy.openItems" :columns="[{ key: 'name', field: 'name', header: copy.counterparty }, { key: 'reference', field: 'reference', header: copy.reference }, { key: 'currency', field: 'currency', header: copy.currency }, { key: 'outstanding', field: 'outstanding', header: copy.outstanding }, { key: 'carrying', field: 'carrying', header: copy.currentCarrying }, { key: 'evidence', field: 'evidence', header: copy.rateEvidence }]"><template #empty>{{ copy.empty }}</template></BsDataTable>
      <BsDataTable :value="view.settlements" data-key="id" :label="copy.settlementHistory" :columns="[{ key: 'date', field: 'date', header: copy.settlementDate }, { key: 'reference', field: 'reference', header: copy.reference }, { key: 'gross', field: 'gross', header: copy.gross }, { key: 'carrying', field: 'carrying', header: copy.currentCarrying }, { key: 'base', field: 'base', header: copy.settlementBase }, { key: 'difference', field: 'difference', header: copy.realizedDifference }, { key: 'evidence', field: 'evidence', header: copy.rateEvidence }]"><template #empty>{{ copy.noSettlements }}</template></BsDataTable>
      <BsDataTable :value="view.allocations" data-key="id" :label="copy.allocationHistory" :columns="[{ key: 'settlement', field: 'settlement', header: copy.reference }, { key: 'item', field: 'item', header: copy.openItems }, { key: 'documentAmount', field: 'documentAmount', header: copy.documentAmount }, { key: 'settlementAmount', field: 'settlementAmount', header: copy.settlementAmount }, { key: 'rate', field: 'rate', header: copy.crossRate }, { key: 'evidence', field: 'evidence', header: copy.conversionEvidence }, { key: 'difference', field: 'difference', header: copy.realizedDifference }, { key: 'residual', field: 'residual', header: copy.roundingResidual }]"><template #empty>{{ copy.noAllocations }}</template></BsDataTable>
    </BsStack>
  </BsCard>
</template>
